CREATE TABLE GameEntitlement(GameEntitlementID INTEGER PRIMARY KEY, UserGameRecordID INTEGER NOT NULL, GameEditionID INTEGER, AcquisitionSourceID INTEGER NOT NULL, OwnedFlag BOOLEAN NOT NULL, AcquisitionDate DATE, AccessEndDate DATE, AccessStatusID INTEGER NOT NULL, StorageLocation VARCHAR, OrganizationFolder VARCHAR, FOREIGN KEY (UserGameRecordID) REFERENCES UserGameRecord(UserGameRecordID), FOREIGN KEY (GameEditionID) REFERENCES GameEdition(GameEditionID), FOREIGN KEY (AcquisitionSourceID) REFERENCES AcquisitionSource(AcquisitionSourceID), FOREIGN KEY (AccessStatusID) REFERENCES AccessStatus(AccessStatusID));
